// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDStakingPoolV2.sol";

/// @notice Stateless construction helper; keeps the combined tax/mining factory below
///         the EIP-3860 initcode limit. No registry, owner, upgrade or fund handling.
contract ADDStakingPoolDeployerV2 {
    function deployImplementation() external returns (address) {
        return address(new ADDStakingPoolV2(msg.sender));
    }
}

contracts/staking-v2/ADDStakingPoolV2.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../openzeppelin/SafeERC20.sol";
import "../openzeppelin/ReentrancyGuard.sol";
import "../FullMath.sol";

interface IADDStakingWrappedV2 {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
}
interface IADDStakingTaxSourceV2 {
    function phase() external view returns (uint8);
    function initializationFactory() external view returns (address);
    function wrappedNative() external view returns (address);
    function quoteToken() external view returns (address);
    function pair() external view returns (address);
}

/// @title ADD permissionless staking / claim mining pool V2: independent principal vesting
/// @notice 独立矿池，无 owner、升级、暂停、改费率、提走本金或奖励的管理入口。
/// @dev Rewards are funded assets, never minted: prepaid ERC20 or recurring ERC20/BNB.
///      address(0) stakingAsset means native
///      coin wrapped by the factory's immutable wrapper. Same-token principal and
///      reward reserves are separate liabilities. No holder loops or automatic payouts.
///      Rebasing/reflection assets and sender-extra-fee tokens are NOT supported.
contract ADDStakingPoolV2 is ReentrancyGuard {
    using SafeERC20 for IERC20Minimal;

    address public constant FEE_RECIPIENT = 0xCb1D21591759E67E93D5054CaEbb5e972229DADd;
    uint256 public constant FEE_BPS = 100;
    uint256 public constant MAX_AMOUNT = type(uint112).max;
    uint256 public constant MAX_DURATION = 3650 days;
    uint8 public constant MAX_HALVINGS = 32;
    uint256 private constant SCALE = 1e36;
    // Integer time weights represent all 32 halvings exactly, with no rate-to-zero.
    uint256 private constant WEIGHT = 1 << 32;

    address public immutable initializationFactory;
    bool public initialized;
    uint256 public constant VERSION = 2;
    uint256 public constant MAX_POSITIONS = 64;
    enum WithdrawalMode { Flexible, Cliff, Batches }
    struct PrincipalLock { WithdrawalMode mode; uint16 initialDays; uint16 intervalDays; uint16 batches; }
    struct Position { uint112 deposited; uint112 withdrawn; uint64 startedAt; }
    struct UnlockView { uint256 withdrawable; uint256 locked; uint256 nextUnlockAt; uint256 livePositions; }
    PrincipalLock public principalLock;
    bool public lockConfigured;
    mapping(address => Position[]) private positions;
    event PrincipalLockConfigured(WithdrawalMode mode, uint16 initialDays, uint16 intervalDays, uint16 batches);
    event StakePositionOpened(address indexed holder, uint256 indexed slot, uint256 received, uint256 startedAt);

    /// @notice 工厂在同一创建交易中、初始化之前写入一次；之后任何人均不可改锁仓规则。
    /// @dev Principal uses wall-clock days, independently of the reward clock (which
    ///      pauses with no stakers). A later deposit never resets an earlier deposit.
    function configurePrincipalLock(PrincipalLock calldata p) external {
        require(msg.sender == initializationFactory && !initialized && !lockConfigured, "Lock configuration forbidden");
        if (p.mode == WithdrawalMode.Flexible) {
            require(p.initialDays == 0 && p.intervalDays == 0 && p.batches == 0, "Invalid flexible lock");
        } else if (p.mode == WithdrawalMode.Cliff) {
            require(p.initialDays >= 1 && p.initialDays <= 3650 && p.intervalDays == 0 && p.batches == 1, "Invalid cliff lock");
        } else {
            require(p.initialDays <= 3650 && p.intervalDays >= 1 && p.batches >= 2 && p.batches <= 365, "Invalid batch lock");
            require(uint256(p.initialDays) + uint256(p.intervalDays) * (p.batches - 1) <= 3650, "Lock exceeds 3650 days");
        }
        principalLock = p; lockConfigured = true;
        emit PrincipalLockConfigured(p.mode, p.initialDays, p.intervalDays, p.batches);
    }

    function _openPosition(address holder, uint256 received) private {
        if (principalLock.mode == WithdrawalMode.Flexible) return;
        Position[] storage list = positions[holder]; uint256 slot = list.length;
        for (uint256 i; i < list.length; ++i) {
            if (list[i].withdrawn == list[i].deposited) { slot = i; break; }
        }
        require(slot < MAX_POSITIONS, "Withdraw old positions before adding more");
        Position memory p = Position(uint112(received), 0, uint64(block.timestamp));
        if (slot == list.length) list.push(p); else list[slot] = p;
        emit StakePositionOpened(holder, slot, received, block.timestamp);
    }

    /// @dev Use cumulative floor(principal * releasedBatches / batches), not a
    ///      rounded per-batch amount. The final batch always unlocks every last unit.
    function _unlocked(Position memory p) private view returns (uint256 vested, uint256 next) {
        if (p.withdrawn == p.deposited) return (p.deposited, 0);
        uint256 first = uint256(p.startedAt) + uint256(principalLock.initialDays) * 1 days;
        if (block.timestamp < first) return (0, first);
        if (principalLock.mode == WithdrawalMode.Cliff) return (p.deposited, 0);
        uint256 interval = uint256(principalLock.intervalDays) * 1 days;
        uint256 released = 1 + (block.timestamp - first) / interval;
        uint256 count = principalLock.batches;
        if (released >= count) return (p.deposited, 0);
        vested = uint256(p.deposited) * released / count;
        // With tiny deposits some batches round to zero; report the next boundary
        // that actually releases another base unit, not a misleading zero release.
        uint256 nextBatch = ((vested + 1) * count + p.deposited - 1) / p.deposited;
        next = first + (nextBatch - 1) * interval;
    }

    function getUnlockInfo(address holder) external view returns (UnlockView memory v) {
        if (principalLock.mode == WithdrawalMode.Flexible) { v.withdrawable = accounts[holder].staked; return v; }
        Position[] storage list = positions[holder];
        for (uint256 i; i < list.length; ++i) {
            Position memory p = list[i]; if (p.deposited == p.withdrawn) continue;
            (uint256 vested, uint256 next) = _unlocked(p);
            v.withdrawable += vested - p.withdrawn; v.locked += p.deposited - vested; ++v.livePositions;
            if (next != 0 && (v.nextUnlockAt == 0 || next < v.nextUnlockAt)) v.nextUnlockAt = next;
        }
    }

    /// @notice 返回稳定槽位的存款记录；取完后槽位可复用，以事件追溯旧记录。
    function getPositions(address holder, uint256 offset, uint256 limit) external view returns (Position[] memory result) {
        require(limit <= MAX_POSITIONS, "Page limit exceeds 64");
        Position[] storage list = positions[holder]; uint256 n = offset >= list.length ? 0 : list.length - offset;
        if (n > limit) n = limit; result = new Position[](n);
        for (uint256 i; i < n; ++i) result[i] = list[offset + i];
    }

    function _consumeUnlocked(address holder, uint256 amount) private {
        if (principalLock.mode == WithdrawalMode.Flexible) return;
        Position[] storage list = positions[holder]; uint256 remaining = amount;
        for (uint256 i; i < list.length && remaining != 0; ++i) {
            Position storage p = list[i]; (uint256 vested,) = _unlocked(p);
            uint256 available = vested - p.withdrawn;
            uint256 take = available < remaining ? available : remaining;
            p.withdrawn += uint112(take); remaining -= take;
        }
        // The whole transaction reverts, including any partially consumed slots.
        require(remaining == 0, "Principal is still locked");
    }
    address public creator; // Informational only. It grants NO special permissions.
    address public rewardToken;
    address public stakingAsset;
    address public stakingToken;
    address public wrappedNative;
    uint256 public createdAt;
    uint256 public initialDuration;
    uint256 public halvingInterval;
    uint8 public halvingCount;
    bool public cycling;
    bool public nativeReward;
    address public linkedToken;
    bool public linkedActivated;
    uint8 public linkedStakeMode; // 0 self token; 1 final V2 LP; 2 custom (zero = native).
    address public linkedCustomStake;
    uint256 public cycleNumber;
    uint256 public cycleBudget;
    uint256 public cycleStartActive;
    uint256 public cycleStartEmitted;

    uint256 public totalStaked;
    uint256 public totalFunded;
    uint256 public totalGrossClaimed;
    uint256 public totalFeesPaid;
    uint256 public lastUpdate;
    // Emission = numerator * weighted active seconds / denominator, carrying fractions.
    uint256 public rateNumerator;
    uint256 public rateDenominator;

    struct Ledger {
        uint256 remaining;
        uint256 emissionFraction;
        uint256 activeElapsed;
        uint256 emitted;
        uint256 index;
        uint256 indexRemainder;
    }
    Ledger private ledger;
    struct Account {
        uint256 staked;
        uint256 index;
        uint256 credit;
        uint256 fraction;
        uint256 grossClaimed;
    }
    mapping(address => Account) public accounts;
    enum FundingMode { Extend, Recalculate }

    struct ScheduleView {
        uint256 remainingRewards;
        uint256 emittedRewards;
        uint256 grossClaimed;
        uint256 fundedRewards;
        uint256 stakedSupply;
        uint256 activeElapsedSeconds;
        uint256 remainingActiveSeconds;
        uint256 estimatedEndTime;
        uint256 currentRateNumerator;
        uint256 currentRateDenominator;
        uint256 currentRewardsPerMinute;
        uint256 nextHalvingInActiveSeconds;
        uint256 halvingsApplied;
        bool pausedForNoStakers;
        bool finished;
    }
    struct AccountView {
        uint256 staked;
        uint256 totalStake;
        uint256 shareBps;
        uint256 earnedGross;
        uint256 claimFee;
        uint256 claimNet;
        uint256 claimedGross;
        uint256 paidFees;
    }
    struct FundingView {
        uint256 assumedReceived;
        uint256 remainingRewardsAfter;
        uint256 remainingActiveSeconds;
        uint256 estimatedEndTime;
        uint256 currentRewardsPerMinute;
    }

    event Staked(address indexed holder, uint256 requested, uint256 received);
    event Withdrawn(address indexed holder, address indexed receiver, uint256 amount, bool unwrapped);
    event RewardsAdded(address indexed funder, uint256 requested, uint256 received, FundingMode mode,
        uint256 numerator, uint256 denominator, uint256 remainingActiveSeconds);
    event RewardClaimed(address indexed holder, address indexed receiver, uint256 gross, uint256 fee);
    event Checkpoint(uint256 emittedNow, uint256 activeElapsed, uint256 remainingRewards);
    event LinkedPoolActivated(address indexed token, address rewardAsset, address stakingAsset);
    event CycleStarted(uint256 indexed cycle, uint256 rewards, uint256 durationSeconds);
    event RewardsDetected(uint256 indexed cycle, uint256 amount, uint256 remainingSeconds);

    constructor(address factory_) {
        require(factory_ != address(0), "Invalid initialization factory");
        initializationFactory = factory_; initialized = true;
    }
    modifier ready() { require(initialized && rewardToken != address(0), "Pool not initialized"); _; }
    modifier activateLinked() {
        if (linkedToken != address(0) && !linkedActivated) _activateLinked();
        _;
    }

    /// @dev The implementation is locked; clones can be initialized once only by their
    ///      deploying factory, after that factory transfers actual initial rewards.
    function initialize(address creator_, address reward_, address stake_, address wrapped_,
        uint256 received, uint256 duration, uint256 interval, uint8 halvings) external {
        require(msg.sender == initializationFactory && !initialized && lockConfigured, "Initialization forbidden");
        require(creator_ != address(0) && reward_.code.length > 0 && wrapped_.code.length > 0,
            "Invalid assets");
        require(stake_ == address(0) || stake_.code.length > 0, "Invalid stake asset");
        require(received > 0 && received <= MAX_AMOUNT && duration > 0 && duration <= MAX_DURATION,
            "Invalid funding or duration");
        require((halvings == 0 && interval == 0) ||
            (halvings > 0 && halvings <= MAX_HALVINGS && interval > 0 && interval <= MAX_DURATION),
            "Invalid halving plan");
        require(IERC20Minimal(reward_).balanceOf(address(this)) >= received, "Unfunded pool");
        initialized = true; creator = creator_; rewardToken = reward_; stakingAsset = stake_;
        wrappedNative = wrapped_; stakingToken = stake_ == address(0) ? wrapped_ : stake_;
        initialDuration = duration; halvingInterval = interval; halvingCount = halvings;
        createdAt = block.timestamp; lastUpdate = block.timestamp;
        totalFunded = received; ledger.remaining = received;
        rateNumerator = received; rateDenominator = duration * WEIGHT;
        _remainingTime(ledger); // Validate the finite time horizon, including all halvings.
    }

    /// @notice 独立循环池允许零首存：等待后续税款，周期1～360天，不减半。
    function initializeCycle(address creator_, address rewardAsset_, address stake_, address wrapped_, uint16 days_)
        external {
        _initializeCycleBase(creator_, wrapped_, days_);
        require(rewardAsset_ == address(0) || rewardAsset_.code.length > 0, "Invalid reward asset");
        require(stake_ == address(0) || stake_.code.length > 0, "Invalid stake asset");
        nativeReward = rewardAsset_ == address(0);
        rewardToken = nativeReward ? wrapped_ : rewardAsset_;
        stakingAsset = stake_; stakingToken = stake_ == address(0) ? wrapped_ : stake_;
    }

    /// @dev Bind and display the known quote/LP at creation. Staking remains gated until
    ///      graduation; a recovery graduation may correct these addresses ONCE before
    ///      any principal or reward liability exists. No owner can set arbitrary assets.
    function initializeLinkedCycle(address creator_, address token_, address wrapped_, uint16 days_,
        uint8 stakeMode_, address customStake_) external {
        _initializeCycleBase(creator_, wrapped_, days_);
        require(token_.code.length > 0 && IADDStakingTaxSourceV2(token_).initializationFactory() == msg.sender,
            "Wrong linked token factory");
        require(stakeMode_ <= 2 && (stakeMode_ == 2 || customStake_ == address(0)), "Invalid staking choice");
        require(stakeMode_ != 2 || customStake_ == address(0) || customStake_.code.length > 0, "Invalid custom stake");
        linkedToken = token_; linkedStakeMode = stakeMode_; linkedCustomStake = customStake_;
        _bindLinkedAssets();
    }

    function _initializeCycleBase(address creator_, address wrapped_, uint16 days_) private {
        require(msg.sender == initializationFactory && !initialized && lockConfigured, "Initialization forbidden");
        require(creator_ != address(0) && wrapped_.code.length > 0, "Invalid cycle assets");
        require(days_ >= 1 && days_ <= 360, "Cycle must be 1 to 360 days");
        initialized = true; cycling = true; creator = creator_; wrappedNative = wrapped_;
        initialDuration = uint256(days_) * 1 days;
        rateDenominator = initialDuration * WEIGHT;
        createdAt = block.timestamp; lastUpdate = block.timestamp;
    }

    function _activateLinked() private {
        IADDStakingTaxSourceV2 source = IADDStakingTaxSourceV2(linkedToken);
        require(source.phase() == 3, "Mining awaits graduation");
        require(totalStaked == 0 && totalFunded == 0 && ledger.emitted == 0, "Linked assets already in use");
        _bindLinkedAssets(); linkedActivated = true; lastUpdate = block.timestamp;
        emit LinkedPoolActivated(linkedToken, nativeReward ? address(0) : rewardToken, stakingAsset);
    }

    function _bindLinkedAssets() private {
        IADDStakingTaxSourceV2 source = IADDStakingTaxSourceV2(linkedToken);
        require(source.wrappedNative() == wrappedNative, "Wrong linked wrapper");
        address reward = source.quoteToken(); address market = source.pair();
        require(reward.code.length > 0 && market.code.length > 0, "Invalid final market");
        rewardToken = reward; nativeReward = reward == wrappedNative;
        stakingAsset = linkedStakeMode == 0 ? linkedToken : linkedStakeMode == 1 ? market : linkedCustomStake;
        stakingToken = stakingAsset == address(0) ? wrappedNative : stakingAsset;
    }

    /// @dev At most 33 iterations regardless of time since last update. After the chosen
    ///      final halving, the last rate persists until the prepaid budget is exhausted.
    function _weightAt(uint256 elapsed) private view returns (uint256 weight, uint256 next) {
        uint256 n = halvingInterval == 0 ? 0 : elapsed / halvingInterval;
        if (n >= halvingCount) return (WEIGHT >> halvingCount, type(uint256).max);
        return (WEIGHT >> n, (n + 1) * halvingInterval);
    }

    function _work(uint256 start, uint256 seconds_) private view returns (uint256 result) {
        while (seconds_ != 0) {
            (uint256 weight, uint256 boundary) = _weightAt(start);
            uint256 span = seconds_;
            if (boundary != type(uint256).max && span > boundary - start) span = boundary - start;
            result += span * weight; start += span; seconds_ -= span;
        }
    }

    function _secondsForWork(uint256 start, uint256 work) private view returns (uint256 result) {
        while (work != 0) {
            (uint256 weight, uint256 boundary) = _weightAt(start);
            uint256 needed = (work - 1) / weight + 1;
            if (boundary == type(uint256).max || needed <= boundary - start) {
                result += needed; break;
            }
            uint256 span = boundary - start;
            result += span; work -= span * weight; start = boundary;
        }
    }

    function _remainingTime(Ledger memory p) private view returns (uint256 result) {
        return _remainingTimeAtRate(p, rateNumerator, rateDenominator);
    }

    function _remainingTimeAtRate(Ledger memory p, uint256 numerator, uint256 denominator)
        private view returns (uint256 result) {
        if (p.remaining == 0) return 0;
        // remaining <= 112 bits, denominator <= 96 bits. Products fit uint256.
        uint256 needed = p.remaining * denominator - p.emissionFraction;
        uint256 weightedSeconds = (needed - 1) / numerator + 1;
        result = _secondsForWork(p.activeElapsed, weightedSeconds);
        require(result <= type(uint64).max - p.activeElapsed, "Schedule too long");
    }

    /// @dev Empty pools do not consume mining time. The pool freezes at the exact
    ///      exhaustion second, rather than advancing the halving clock during downtime.
    function _preview() private view returns (Ledger memory p) {
        p = ledger;
        if (totalStaked == 0 || p.remaining == 0) return p;
        uint256 dt = block.timestamp - lastUpdate;
        uint256 left = _remainingTime(p);
        uint256 emitted;
        if (dt >= left) {
            dt = left; emitted = p.remaining; p.emissionFraction = 0;
        } else {
            uint256 scaled = _work(p.activeElapsed, dt) * rateNumerator + p.emissionFraction;
            emitted = scaled / rateDenominator; p.emissionFraction = scaled % rateDenominator;
        }
        p.activeElapsed += dt; p.remaining -= emitted; p.emitted += emitted;
        // Remainder carry prevents frequent checkpoints from destroying accrued dust.
        // After stake changes, less than one base unit of aggregate fractional dust can
        // pass to the next stake set. It never expands the funded liability.
        uint256 indexedRewards = emitted * SCALE + p.indexRemainder;
        p.index += indexedRewards / totalStaked; p.indexRemainder = indexedRewards % totalStaked;
    }

    function _checkpoint(bool syncRewards, uint256 nativePrincipal) private {
        Ledger memory p = _preview();
        if (p.emitted != ledger.emitted) emit Checkpoint(p.emitted - ledger.emitted, p.activeElapsed, p.remaining);
        ledger = p; lastUpdate = block.timestamp;
        if (cycling && syncRewards) _syncRewards(nativePrincipal);
    }

    function checkpoint() external nonReentrant activateLinked ready { _checkpoint(true, 0); }

    /// @dev Only genuinely unaccounted surplus is new revenue. Existing principal,
    ///      unclaimed rewards and rounding reserves must never be counted a second time.
    ///      Native staking msg.value is excluded until credited as PRINCIPAL by stake().
    function _syncRewards(uint256 nativePrincipal) private {
        if (nativeReward) {
            uint256 nativeSurplus = address(this).balance - nativePrincipal;
            if (nativeSurplus != 0) IADDStakingWrappedV2(wrappedNative).deposit{value:nativeSurplus}();
        }
        uint256 balance = IERC20Minimal(rewardToken).balanceOf(address(this));
        uint256 protected = protectedBalance(rewardToken);
        require(balance >= protected, "Insolvent reward asset");
        uint256 received = balance - protected;
        // Excess beyond the lifetime arithmetic cap must not let a donation freeze claims.
        uint256 capacity = MAX_AMOUNT - totalFunded;
        if (received > capacity) received = capacity;
        if (received == 0) return;
        uint256 left = _remainingTime(ledger);
        if (left == 0) {
            left = initialDuration; cycleNumber++;
            cycleBudget = 0; cycleStartActive = ledger.activeElapsed; cycleStartEmitted = ledger.emitted;
            emit CycleStarted(cycleNumber, received, left);
        }
        totalFunded += received; ledger.remaining += received; cycleBudget += received;
        rateNumerator = ledger.remaining; rateDenominator = left * WEIGHT;
        ledger.emissionFraction = 0;
        _remainingTime(ledger);
        emit RewardsDetected(cycleNumber, received, left);
    }

    /// @notice 显式支付循环奖励；普通ERC20转账/BNB转账也可，质押/领取时自动识别。
    function fundCycle(uint256 amount, uint256 minimumReceived) external payable nonReentrant activateLinked ready
        returns (uint256 received) {
        require(cycling && amount > 0, "Not cycle funding");
        require(nativeReward ? msg.value == amount : msg.value == 0, "Wrong funding native value");
        _checkpoint(true, msg.value);
        uint256 beforeBalance = IERC20Minimal(rewardToken).balanceOf(address(this));
        if (nativeReward) IADDStakingWrappedV2(wrappedNative).deposit{value:msg.value}();
        else IERC20Minimal(rewardToken).safeTransferFrom(msg.sender, address(this), amount);
        received = IERC20Minimal(rewardToken).balanceOf(address(this)) - beforeBalance;
        require(received > 0 && received >= minimumReceived, "Insufficient rewards received");
        require(received <= MAX_AMOUNT - totalFunded, "Funding cap exceeded");
        _syncRewards(0);
    }

    function _settle(address holder) private {
        Account storage a = accounts[holder];
        uint256 delta = ledger.index - a.index;
        uint256 fraction = mulmod(a.staked, delta, SCALE) + a.fraction;
        a.credit += FullMath.mulDiv(a.staked, delta, SCALE) + fraction / SCALE;
        a.fraction = fraction % SCALE; a.index = ledger.index;
    }

    /// @notice ERC20 先授权本矿池，BNB 传入同额 msg.value；到账多少记录多少本金。
    function stake(uint256 amount, uint256 minimumReceived) external payable nonReentrant activateLinked ready returns (uint256 received) {
        require(amount > 0, "Zero stake");
        require(stakingAsset == address(0) ? msg.value == amount : msg.value == 0, "Wrong native value");
        _checkpoint(true, msg.value); _settle(msg.sender);
        uint256 beforeBalance = IERC20Minimal(stakingToken).balanceOf(address(this));
        if (stakingAsset == address(0)) {
            require(msg.value == amount, "Wrong native value");
            IADDStakingWrappedV2(wrappedNative).deposit{value: amount}();
        } else {
            require(msg.value == 0, "Unexpected native value");
            IERC20Minimal(stakingToken).safeTransferFrom(msg.sender, address(this), amount);
        }
        received = IERC20Minimal(stakingToken).balanceOf(address(this)) - beforeBalance;
        require(received > 0 && received >= minimumReceived, "Insufficient stake received");
        require(totalStaked + received <= MAX_AMOUNT, "Stake cap exceeded");
        _openPosition(msg.sender, received);
        totalStaked += received; accounts[msg.sender].staked += received;
        _requireSolvent(stakingToken);
        emit Staked(msg.sender, amount, received);
    }

    /// @notice 取回已解锁本金，独立于领取奖励；native 池可选择 BNB 或 WBNB。
    function withdraw(uint256 amount, address payable receiver, bool unwrapNative) external ready nonReentrant {
        _validReceiver(receiver); require(amount > 0 && amount <= accounts[msg.sender].staked, "Invalid withdrawal");
        require(!unwrapNative || stakingAsset == address(0), "Not a native stake pool");
        // Principal exit deliberately does not depend on detecting new reward transfers.
        _checkpoint(false, 0); _settle(msg.sender);
        _consumeUnlocked(msg.sender, amount);
        accounts[msg.sender].staked -= amount; totalStaked -= amount;
        if (unwrapNative) {
            uint256 beforeBalance = IERC20Minimal(stakingToken).balanceOf(address(this));
            IADDStakingWrappedV2(wrappedNative).withdraw(amount);
            require(IERC20Minimal(stakingToken).balanceOf(address(this)) == beforeBalance - amount, "Unexpected asset debit");
            (bool ok,) = receiver.call{value: amount}(""); require(ok, "Native payment failed");
        } else {
            _payExact(stakingToken, receiver, amount);
        }
        _requireSolvent(stakingToken);
        emit Withdrawn(msg.sender, receiver, amount, unwrapNative);
    }

    /// @notice 任何人支付矿币追加。Extend 保持当前减半曲线、延长时间；Recalculate
    ///         保持当前预计结束时点、重算后续速度；已经产生的奖励绝不重新分配。
    /// @dev Recalculate is unavailable after exhaustion (there is no remaining time).
    ///      Extend can restart an exhausted pool at its previous rate/halving position.
    function addRewards(uint256 amount, uint256 minimumReceived, FundingMode mode)
        external ready nonReentrant returns (uint256 received) {
        require(!cycling, "Use fundCycle for cyclic rewards");
        require(amount > 0, "Zero rewards"); _checkpoint(false, 0);
        uint256 left = _remainingTime(ledger);
        require(mode != FundingMode.Recalculate || left != 0, "No remaining mining time");
        uint256 beforeBalance = IERC20Minimal(rewardToken).balanceOf(address(this));
        IERC20Minimal(rewardToken).safeTransferFrom(msg.sender, address(this), amount);
        received = IERC20Minimal(rewardToken).balanceOf(address(this)) - beforeBalance;
        require(received > 0 && received >= minimumReceived, "Insufficient rewards received");
        require(totalFunded + received <= MAX_AMOUNT, "Funding cap exceeded");
        totalFunded += received; ledger.remaining += received;
        if (mode == FundingMode.Recalculate) {
            rateNumerator = ledger.remaining;
            rateDenominator = _work(ledger.activeElapsed, left);
            ledger.emissionFraction = 0;
        }
        uint256 newLeft = _remainingTime(ledger);
        _requireSolvent(rewardToken);
        emit RewardsAdded(msg.sender, amount, received, mode, rateNumerator, rateDenominator, newLeft);
    }

    /// @dev Charge floor(lifetimeGross/100), retaining fractional fee across claims so
    ///      splitting one account's claims cannot bypass the 1% fee through rounding.
    function claim(address receiver) external nonReentrant activateLinked ready returns (uint256 net) {
        return _claim(receiver, true);
    }

    /// @notice BNB奖励可选择接收WBNB，平台维护费仍以BNB支付。
    function claimWrapped(address receiver) external nonReentrant activateLinked ready returns (uint256 net) {
        return _claim(receiver, false);
    }

    function _claim(address receiver, bool unwrapReward) private returns (uint256 net) {
        _validReceiver(receiver); _checkpoint(true, 0); _settle(msg.sender);
        Account storage a = accounts[msg.sender]; uint256 gross = a.credit;
        if (gross == 0) return 0;
        uint256 fee = (a.grossClaimed + gross) / 100 - a.grossClaimed / 100;
        a.credit = 0; a.grossClaimed += gross; totalGrossClaimed += gross; totalFeesPaid += fee;
        require(totalGrossClaimed <= ledger.emitted, "Reward liability exceeded");
        net = gross - fee;
        if (nativeReward) {
            uint256 unwrapped = fee + (unwrapReward ? net : 0);
            if (unwrapped != 0) {
                uint256 beforeBalance = IERC20Minimal(rewardToken).balanceOf(address(this));
                IADDStakingWrappedV2(wrappedNative).withdraw(unwrapped);
                require(IERC20Minimal(rewardToken).balanceOf(address(this)) == beforeBalance - unwrapped, "Unexpected asset debit");
            }
            if (fee != 0) _sendNative(FEE_RECIPIENT, fee);
            if (net != 0) {
                if (unwrapReward) _sendNative(receiver, net);
                else _payExact(rewardToken, receiver, net);
            }
        } else {
            if (fee != 0) _payExact(rewardToken, FEE_RECIPIENT, fee);
            if (net != 0) _payExact(rewardToken, receiver, net);
        }
        _requireSolvent(rewardToken);
        emit RewardClaimed(msg.sender, receiver, gross, fee);
    }

    function _sendNative(address receiver, uint256 amount) private {
        (bool ok,) = payable(receiver).call{value:amount}(""); require(ok, "Native payment failed");
    }

    function _validReceiver(address receiver) private view {
        require(receiver != address(0) && receiver != address(this), "Invalid receiver");
    }

    function _payExact(address asset, address receiver, uint256 amount) private {
        uint256 beforeBalance = IERC20Minimal(asset).balanceOf(address(this));
        IERC20Minimal(asset).safeTransfer(receiver, amount);
        require(IERC20Minimal(asset).balanceOf(address(this)) == beforeBalance - amount, "Unexpected asset debit");
    }

    /// @notice Protected amount includes all not-yet-claimed reward dust; no administrator
    ///         can recover it. Direct transfers are never principal; matching-asset
    ///         surplus becomes rewards only for cycling pools, at the next sync.
    function protectedBalance(address asset) public view returns (uint256 amount) {
        if (asset == stakingToken) amount = totalStaked;
        if (asset == rewardToken) amount += totalFunded - totalGrossClaimed;
    }

    function _requireSolvent(address asset) private view {
        require(IERC20Minimal(asset).balanceOf(address(this)) >= protectedBalance(asset), "Insolvent asset");
    }

    function getSchedule() external view ready returns (ScheduleView memory s) {
        Ledger memory p = _preview(); uint256 left = _remainingTime(p);
        (uint256 weight, uint256 next) = _weightAt(p.activeElapsed);
        s = ScheduleView(p.remaining, p.emitted, totalGrossClaimed, totalFunded, totalStaked,
            p.activeElapsed, left, left == 0 ? 0 : block.timestamp + left,
            rateNumerator * weight, rateDenominator,
            FullMath.mulDiv(rateNumerator, weight * 60, rateDenominator),
            next == type(uint256).max ? 0 : next - p.activeElapsed,
            halvingInterval == 0 ? 0 : p.activeElapsed / halvingInterval,
            totalStaked == 0 && left != 0, left == 0);
        if (s.halvingsApplied > halvingCount) s.halvingsApplied = halvingCount;
    }

    function getAccount(address holder) external view ready returns (AccountView memory v) {
        Ledger memory p = _preview(); Account memory a = accounts[holder];
        uint256 delta = p.index - a.index;
        uint256 gross = a.credit + FullMath.mulDiv(a.staked, delta, SCALE)
            + (mulmod(a.staked, delta, SCALE) + a.fraction) / SCALE;
        uint256 fee = (a.grossClaimed + gross) / 100 - a.grossClaimed / 100;
        return AccountView(a.staked, totalStaked, totalStaked == 0 ? 0 : FullMath.mulDiv(a.staked, 10000, totalStaked),
            gross, fee, gross - fee, a.grossClaimed, a.grossClaimed / 100);
    }

    /// @notice 追加确认页预览。received 是预计实际到账量；代币自身转账税及交易打包
    ///         时间可能使实际结果不同，应同时使用 minimumReceived 防止少到账。
    function previewAddRewards(uint256 received, FundingMode mode) external view ready returns (FundingView memory v) {
        require(!cycling, "Use cycle information");
        require(received > 0 && totalFunded + received <= MAX_AMOUNT, "Invalid additional funding");
        Ledger memory p = _preview(); uint256 left = _remainingTime(p);
        require(mode != FundingMode.Recalculate || left != 0, "No remaining mining time");
        p.remaining += received;
        uint256 numerator = rateNumerator; uint256 denominator = rateDenominator;
        if (mode == FundingMode.Recalculate) {
            numerator = p.remaining; denominator = _work(p.activeElapsed, left); p.emissionFraction = 0;
        }
        uint256 newLeft = _remainingTimeAtRate(p, numerator, denominator);
        (uint256 weight,) = _weightAt(p.activeElapsed);
        return FundingView(received, p.remaining, newLeft, block.timestamp + newLeft,
            FullMath.mulDiv(numerator, weight * 60, denominator));
    }

    /// @notice 循环统计可归零，但全局已赚未领取权益从不清零。
    function getCycleInfo() external view returns (uint256 number, uint256 duration, uint256 budget,
        uint256 emittedThisCycle, uint256 elapsedThisCycle, uint256 pendingUnrecognized, bool awaitingGraduation) {
        awaitingGraduation = linkedToken != address(0) && !linkedActivated;
        Ledger memory p = _preview();
        number = cycleNumber; duration = initialDuration; budget = cycleBudget;
        emittedThisCycle = p.emitted - cycleStartEmitted; elapsedThisCycle = p.activeElapsed - cycleStartActive;
        if (rewardToken != address(0)) {
            uint256 balance = IERC20Minimal(rewardToken).balanceOf(address(this));
            uint256 protected = protectedBalance(rewardToken);
            pendingUnrecognized = balance > protected ? balance - protected : 0;
            if (nativeReward) pendingUnrecognized += address(this).balance;
        }
    }

    // Keep this cheap: the existing tax token forwards marketing BNB with 30,000 gas.
    // Wrapping, balance detection and accounting happen on a later user interaction.
    receive() external payable {
        require(msg.sender == wrappedNative || nativeReward || linkedToken != address(0), "Use stake for native coin");
    }
}

contracts/staking-v2/ADDStakingTaxFactor.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "../tax-v1/ADDAutoTaxFactoryV1.sol";
import "./ADDStakingPoolDeployerV2.sol";

/// @notice ADD 新税收发行入口：一笔交易创建代币和无owner循环矿池。
/// @dev The inherited ordinary createToken path remains available. This is a NEW
///      factory candidate, not an upgrade of the already-deployed factory. Portal
///      must register this address before it can launch tokens. Mining starts only
///      after graduation and uses the final quote/LP, including recovery graduation.
contract ADDStakingTaxFactoryV2 is ADDAutoTaxFactoryV1 {
    address public immutable stakingImplementation;
    mapping(address => address) public stakingOf;
    mapping(address => bool) public isStakingPool;
    address[] private stakingPools;
    mapping(address => address[]) private creatorStakingPools;
    struct StakingConfig { ADDStakingPoolV2.PrincipalLock principalLock; uint16 cycleDays; uint8 stakeMode; address customStake; }
    event TokenStakingCreated(address indexed token, address indexed pool, address indexed creator,
        uint16 cycleDays, uint8 stakeMode, address customStake);

    /// @dev Deploy ADDStakingPoolDeployerV2 first and verify its compiled bytecode.
    ///      The helper merely constructs an implementation whose initialization authority
    ///      is this factory. There are no later calls or trust/upgrade permissions to it.
    constructor(address portal_, address poolDeployer_) ADDAutoTaxFactoryV1(portal_) {
        require(poolDeployer_.code.length > 0, "Invalid staking deployer");
        address deployed = ADDStakingPoolDeployerV2(poolDeployer_).deployImplementation();
        require(deployed.code.length > 0 && ADDStakingPoolV2(payable(deployed)).initializationFactory() == address(this),
            "Wrong staking implementation");
        stakingImplementation = deployed;
    }

    function createTokenWithStaking(Launch calldata p, ADDAutoTaxTokenV1.Config calldata requested,
        StakingConfig calldata s) external nonReentrant returns (address token, address miningPool) {
        require(block.timestamp <= p.deadline, "Launch expired");
        require(requested.marketingBps > 0, "Mining needs marketing allocation");
        token = predictToken(p.salt);
        require(address(bytes20(p.salt)) == msg.sender && token == p.expectedAddress
            && uint16(uint160(token)) == uint16(tokenAddressSuffix), "Invalid prepared address");
        bytes memory code = creationCode(); bytes32 salt = p.salt; address created;
        assembly ("memory-safe") { created := create2(0,add(code,32),mload(code),salt) }
        require(created == token && created != address(0), "Token creation failed");

        address wrapped = IADDTaxRouter(router).WETH();
        miningPool = ADDTaxClones.clone(stakingImplementation);
        ADDStakingPoolV2(payable(miningPool)).configurePrincipalLock(s.principalLock);
        ADDAutoTaxTokenV1.Config memory c = requested;
        c.marketingWallet = miningPool; // The marketing share is the mining income.

        address dividend;
        if (c.dividendBps > 0) {
            dividend = ADDTaxClones.clone(dividendImplementation);
            address reward = c.rewardMode == ADDAutoTaxTokenV1.RewardMode.Native ? wrapped
                : c.rewardMode == ADDAutoTaxTokenV1.RewardMode.Self ? token : c.rewardToken;
            ADDClaimDividendV1(payable(dividend)).initialize(token,reward,wrapped,
                c.rewardMode == ADDAutoTaxTokenV1.RewardMode.Native,c.minimumHolding);
        }
        address receiver = address(new ADDTaxSwapReceiverV1(token));
        ADDAutoTaxTokenV1(payable(token)).initialize(p.name,p.symbol,portal,router,p.supply,dividend,receiver,c);
        isCreatedToken[token] = true; creatorOf[token] = msg.sender; dividendOf[token] = dividend;
        stakingOf[token] = miningPool; isStakingPool[miningPool] = true;
        stakingPools.push(miningPool); creatorStakingPools[msg.sender].push(miningPool);
        IADDPortalAdmissionV1(portal).registerFactoryToken(ADDAdmissionV1(token,msg.sender,p.quoteAsset,p.supply,
            p.targetBNB,p.quoteTarget,p.deadline,p.customTarget,true,p.metadataURI));
        ADDStakingPoolV2(payable(miningPool)).initializeLinkedCycle(msg.sender,token,wrapped,
            s.cycleDays,s.stakeMode,s.customStake);
        emit TokenCreated(token,msg.sender,dividend,p.supply);
        emit TokenStakingCreated(token,miningPool,msg.sender,s.cycleDays,s.stakeMode,s.customStake);
    }

    function stakingPoolCount() external view returns (uint256) { return stakingPools.length; }
    function getStakingPools(address creator_, uint256 offset, uint256 limit) external view returns (address[] memory result) {
        require(limit <= 100, "Page limit exceeds 100");
        address[] storage source = creator_ == address(0) ? stakingPools : creatorStakingPools[creator_];
        uint256 size = offset >= source.length ? 0 : source.length-offset;
        if(size > limit) size = limit;
        result = new address[](size);
        for(uint256 i; i<size; ++i) result[i]=source[offset+i];
    }
}

contracts/tax-v1/ADDAutoTaxFactoryV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDAutoTaxTokenV1.sol";

interface IADDAutoTaxPortalV1 { function router() external view returns (address); }

/// @notice New-V1 factory glue. Owner registers THIS factory in Portal once.
/// @dev Immutable implementations, no factory owner or upgrade path. A launch with
///      zero dividend allocation creates no dividend ledger. A positive allocation
///      creates one dedicated ledger atomically; failed admission rolls everything back.
contract ADDAutoTaxFactoryV1 is ReentrancyGuard {
    address public immutable portal;
    address public immutable router;
    address public immutable implementation;
    address public immutable dividendImplementation;
    bytes2 public constant tokenAddressSuffix = 0x1111;
    mapping(address => bool) public isCreatedToken;
    mapping(address => address) public creatorOf;
    mapping(address => address) public dividendOf;
    struct Launch {
        string name; string symbol; uint256 supply; bytes32 salt; address expectedAddress;
        address quoteAsset; uint256 targetBNB; uint256 quoteTarget; uint256 deadline;
        bool customTarget; string metadataURI;
    }
    event TokenCreated(address indexed token, address indexed creator, address indexed dividend, uint256 supply);
    constructor(address portal_) {
        require(portal_.code.length > 0,"Invalid Portal");
        portal = portal_; router = IADDAutoTaxPortalV1(portal_).router();
        require(router.code.length > 0,"Invalid router");
        implementation = address(new ADDAutoTaxTokenV1());
        dividendImplementation = address(new ADDClaimDividendV1());
    }
    function portalFactoryVersion() external pure returns (uint256) { return 1; }
    function creationCode() public view returns (bytes memory) {
        return abi.encodePacked(ADDTaxClones.code(implementation),portal);
    }
    function getDeploymentInfo() external view returns (address,bytes32,bytes2) {
        return (address(this),keccak256(creationCode()),tokenAddressSuffix);
    }
    function predictToken(bytes32 salt) public view returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff),address(this),salt,keccak256(creationCode()))))));
    }
    function createToken(Launch calldata p, ADDAutoTaxTokenV1.Config calldata c) external nonReentrant returns (address token) {
        require(block.timestamp <= p.deadline,"Launch expired");
        token = predictToken(p.salt);
        require(address(bytes20(p.salt)) == msg.sender && token == p.expectedAddress
            && uint16(uint160(token)) == uint16(tokenAddressSuffix),"Invalid prepared address");
        bytes memory code = creationCode(); bytes32 salt = p.salt; address created;
        assembly ("memory-safe") { created := create2(0,add(code,32),mload(code),salt) }
        require(created != address(0) && created == token,"Token creation failed");
        address ledger;
        if (c.dividendBps > 0) {
            ledger = ADDTaxClones.clone(dividendImplementation);
            address wrapped = IADDTaxRouter(router).WETH();
            address reward = c.rewardMode == ADDAutoTaxTokenV1.RewardMode.Native ? wrapped
                : c.rewardMode == ADDAutoTaxTokenV1.RewardMode.Self ? token : c.rewardToken;
            ADDClaimDividendV1(payable(ledger)).initialize(token,reward,wrapped,
                c.rewardMode == ADDAutoTaxTokenV1.RewardMode.Native,c.minimumHolding);
        }
        address receiver = address(new ADDTaxSwapReceiverV1(token));
        ADDAutoTaxTokenV1(payable(token)).initialize(p.name,p.symbol,portal,router,p.supply,ledger,receiver,c);
        isCreatedToken[token] = true; creatorOf[token] = msg.sender; dividendOf[token] = ledger;
        IADDPortalAdmissionV1(portal).registerFactoryToken(ADDAdmissionV1(token,msg.sender,p.quoteAsset,p.supply,
            p.targetBNB,p.quoteTarget,p.deadline,p.customTarget,true,p.metadataURI));
        emit TokenCreated(token,msg.sender,ledger,p.supply);
    }
}

contracts/tax-v1/ADDAutoTaxTokenV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../openzeppelin/ERC20.sol";
import "../tax/ADDTaxPriceGuard.sol";
import "../portal-v1/IADDPortalV1.sol";
import "./ADDClaimDividendV1.sol";
import "./ADDTaxSwapReceiverV1.sol";

/// @title ADD 自动税收代币 / post-graduation tax token, candidate V1
/// @notice 营销、销毁、自动加池均在本合约；仅启用分红时绑定独立领取合约。
/// @dev New Portal V1 only, not the historical v13 ABI. No owner, tax setter, mint,
///      sweep or upgrade entry. Graduation/refund hooks can ONLY come from bound Portal.
///      Buy/sell means transfers involving verified pairs of the configured V2 factory;
///      manual liquidity adds/removes cannot reliably be distinguished from swaps.
contract ADDAutoTaxTokenV1 is ERC20, ReentrancyGuard {
    using SafeERC20 for IERC20Minimal;
    using ADDTaxPriceGuard for ADDTaxPriceGuard.State;
    enum RewardMode { Native, Token, Self }
    enum Phase { AwaitingAdmission, Active, Migrating, Graduated, RefundOnly, Refunded }
    struct Config {
        uint16 buyTaxBps; uint16 sellTaxBps;
        uint16 marketingBps; uint16 burnBps; uint16 dividendBps; uint16 liquidityBps;
        address marketingWallet;
        RewardMode rewardMode; address rewardToken; uint256 minimumHolding;
    }

    error OnlyPortal();
    error OnlyAutomaticStage();
    error PoolTransfersLocked();
    error TokenInitializationForbidden();
    error InvalidLaunch();
    error InvalidMetadata();
    error InvalidIntegerTax();
    error InvalidAllocation();
    error InvalidMarketingWallet();
    error InvalidRewardAsset();
    error InvalidDividendConfig();
    error UnexpectedDividendLedger();
    error InvalidDEX();
    error WrongDividendBinding();
    error InvalidAdmissionPhase();
    error InvalidMigrationPhase();
    error InvalidGraduationPhase();
    error InvalidRefundPhase();
    error InvalidRefundCompletion();
    error InvalidPair();
    error WrongPairToken();
    error WrongPairFactory();
    error PoolCannotReceiveMarketing();
    error MintForbidden();
    error InvalidTransfer();
    error UsePortalToSell();
    error NotAdmitted();
    error MigrationTransferOnly();
    error NestedTaxTransfer();
    error TaxTradeGasLimitTooLow();
    error NotGraduated();
    error TaxProcessingGasLimitTooLow();
    error EmptySplit();
    error SwapNeedsMinimum();
    error UnexpectedSwapDebit();
    error InsufficientSwapOutput();
    error RoundedSwapCapacity();
    error InvalidRewardFunding();
    error LPAmountTooSmall();
    error InvalidLPConsumption();
    error LPNotBurned();
    error NotNativeQuote();
    error MarketingNativeRejected();
    error UnexpectedMarketingDebit();
    error OnlyWrappedNative();

    address public immutable initializationFactory;
    address public constant DEAD = address(0xdead);
    uint256 public constant AUTO_CALL_GAS = 3_200_000;
    uint256 private constant TRADE_GAS_RESERVE = 300_000;
    bool private initialized;
    bool private minted;
    bool public automaticProcessing;
    address public portal;
    address public router;
    address public dexFactory;
    address public wrappedNative;
    address public pair;
    address public quoteToken;
    address public dividend;
    address public swapReceiver;
    address public rewardAsset;
    uint256 public initialSupply;
    uint256 public graduatedAt;
    uint256 public maximumProcessAmount;
    Phase public phase;
    Config public config;
    ADDTaxPriceGuard.State private prices;

    // Separate liabilities: balanceOf(this) includes unsplit tax, retained LP tokens,
    // and self-token dividends. Quote balances must never be recycled as fresh tax.
    uint256 public pendingMarketing;
    uint256 public pendingDividendQuote;
    uint256 public pendingSelfReward;
    uint256 public pendingLPToken;
    uint256 public pendingLPQuote;
    uint256 public totalBurned;
    uint256 public totalLiquidity;

    event PhaseChanged(Phase phase);
    event TradeTax(address indexed from, address indexed to, uint256 amount);
    event TaxProcessed(uint256 tokens, uint256 burned, uint256 quoteReceived);
    event MarketingPaid(address indexed wallet, uint256 amount, bool nativePayment);
    event LiquidityBurned(uint256 tokenAmount, uint256 quoteAmount, uint256 lpAmount);
    event AutomaticStage(bytes4 indexed selector, bool success);
    event AutomaticProcessingDeferred();

    constructor() ERC20("", "") { initializationFactory = msg.sender; initialized = true; }
    modifier onlyPortal() { if (msg.sender != portal) revert OnlyPortal(); _; }
    modifier onlySelf() { if (msg.sender != address(this)) revert OnlyAutomaticStage(); _; }
    function portalTokenVersion() external pure returns (uint256) { return 1; }
    function liquidityAdded() external view returns (bool) { return phase == Phase.Graduated; }

    /// @notice 累计处理门槛从成功毕业时起，每满365天减半；不足一年不减。
    /// @dev Derive from the fixed initial supply, never totalSupply/burned balances.
    ///      Read-only: no keeper transaction, owner setter, or reset on processing.
    ///      Shifts >=256 safely produce zero; clamp to one smallest token unit.
    ///      The per-batch maximumProcessAmount and dividend minimum do not halve.
    function processingThreshold() public view returns (uint256 amount) {
        amount = initialSupply / 100_000;
        uint256 start = graduatedAt;
        // Written once from a successful earlier transaction: start <= block.timestamp.
        if (start != 0) { unchecked { amount >>= (block.timestamp - start) / 365 days; } }
        if (amount == 0) amount = 1;
    }

    /// @notice Parameters are fixed for the life of this token. Amounts use 18 decimals;
    ///         percentages are integer percentages encoded in basis points (1% = 100).
    function initialize(string calldata name_, string calldata symbol_, address portal_, address router_,
        uint256 supply, address dividend_, address receiver_, Config calldata c) external {
        if (!(msg.sender == initializationFactory && !initialized)) revert TokenInitializationForbidden();
        if (!(portal_.code.length > 0 && router_.code.length > 0 && supply >= 2
            && supply / 2 <= type(uint112).max)) revert InvalidLaunch();
        if (!(bytes(name_).length > 0 && bytes(name_).length <= 128
            && bytes(symbol_).length > 0 && bytes(symbol_).length <= 32)) revert InvalidMetadata();
        if (!(c.buyTaxBps <= 1000 && c.sellTaxBps <= 1000 && c.buyTaxBps + c.sellTaxBps > 0
            && c.buyTaxBps % 100 == 0 && c.sellTaxBps % 100 == 0)) revert InvalidIntegerTax();
        if (!(uint256(c.marketingBps) + c.burnBps + c.dividendBps + c.liquidityBps == 10000
            && c.marketingBps % 100 == 0 && c.burnBps % 100 == 0
            && c.dividendBps % 100 == 0 && c.liquidityBps % 100 == 0)) revert InvalidAllocation();
        if (!(c.marketingBps == 0 || (c.marketingWallet != address(0) && c.marketingWallet != DEAD
            && c.marketingWallet != address(this) && c.marketingWallet != portal_
            && c.marketingWallet != router_ && c.marketingWallet != dividend_ && c.marketingWallet != receiver_))) revert InvalidMarketingWallet();
        if (!(c.rewardMode == RewardMode.Token ? c.rewardToken.code.length > 0
            && c.rewardToken != address(this) : c.rewardToken == address(0))) revert InvalidRewardAsset();
        if (c.dividendBps > 0) {
            if (!(dividend_.code.length > 0 && c.minimumHolding >= 10_000 ether
                && c.minimumHolding <= supply)) revert InvalidDividendConfig();
        } else if (!(dividend_ == address(0))) revert UnexpectedDividendLedger();
        initialized = true; portal = portal_; router = router_; initialSupply = supply;
        dexFactory = IADDTaxRouter(router_).factory(); wrappedNative = IADDTaxRouter(router_).WETH();
        if (!(dexFactory.code.length > 0 && wrappedNative.code.length > 0)) revert InvalidDEX();
        dividend = dividend_; config = c;
        swapReceiver = receiver_;
        rewardAsset = c.rewardMode == RewardMode.Native ? wrappedNative
            : c.rewardMode == RewardMode.Self ? address(this) : c.rewardToken;
        if (dividend_ != address(0)) {
            ADDClaimDividendV1 ledger = ADDClaimDividendV1(payable(dividend_));
            if (!(ledger.token() == address(this) && ledger.rewardToken() == rewardAsset
                && ledger.minimumHolding() == c.minimumHolding)) revert WrongDividendBinding();
        }
        // Relative to actual supply, not the retired fixed one-billion supply.
        maximumProcessAmount = supply / 10_000;
        if (maximumProcessAmount == 0) maximumProcessAmount = 1;
        _initializeMetadata(name_, symbol_); _mint(portal_, supply);
    }

    function onPortalAdmission(address pair_) external onlyPortal {
        if (!(phase == Phase.AwaitingAdmission && initialized)) revert InvalidAdmissionPhase();
        _bindPair(pair_); phase = Phase.Active; emit PhaseChanged(phase);
    }
    function onPortalMigrationStart(address pair_) external onlyPortal {
        if (!(phase == Phase.Active)) revert InvalidMigrationPhase();
        // Alternative-asset graduation supplies the actual final pair. Hook and
        // quote binding roll back together if graduation fails.
        _bindPair(pair_); phase = Phase.Migrating; emit PhaseChanged(phase);
    }
    function onPortalGraduation() external onlyPortal {
        if (!(phase == Phase.Migrating)) revert InvalidGraduationPhase();
        graduatedAt = block.timestamp;
        phase = Phase.Graduated; emit PhaseChanged(phase);
        // Warm the automatic price observation after LP reserves are installed.
        _observe(address(this), quoteToken);
    }
    function onPortalRefundStart() external onlyPortal {
        if (!(phase == Phase.Active)) revert InvalidRefundPhase();
        phase = Phase.RefundOnly; emit PhaseChanged(phase);
    }
    function onPortalRefundComplete() external onlyPortal {
        if (!(phase == Phase.RefundOnly)) revert InvalidRefundCompletion();
        phase = Phase.Refunded; emit PhaseChanged(phase);
    }
    function _bindPair(address market) private {
        if (!(market.code.length > 0)) revert InvalidPair();
        address a = _addressGetter(market, abi.encodeWithSignature("token0()"));
        address b = _addressGetter(market, abi.encodeWithSignature("token1()"));
        if (!(a == address(this) || b == address(this))) revert WrongPairToken();
        if (!(_addressGetter(dexFactory, abi.encodeWithSignature("getPair(address,address)", a, b)) == market)) revert WrongPairFactory();
        if (!(config.marketingBps == 0 || config.marketingWallet != market)) revert PoolCannotReceiveMarketing();
        pair = market; quoteToken = a == address(this) ? b : a;
    }
    function _addressGetter(address target, bytes memory input) private view returns (address value) {
        bool ok; uint256 result; uint256 size;
        assembly ("memory-safe") {
            let p := mload(0x40)
            ok := staticcall(20000, target, add(input,32), mload(input), p, 32)
            size := returndatasize()
            result := mload(p)
        }
        if (ok && size == 32 && result <= type(uint160).max) value = address(uint160(result));
    }
    function isTaxPool(address account) public view returns (bool) {
        if (account == pair && account != address(0)) return true;
        if (account.code.length == 0 || account == portal || account == address(this) || account == dividend) return false;
        address a = _addressGetter(account, abi.encodeWithSignature("token0()"));
        address b = _addressGetter(account, abi.encodeWithSignature("token1()"));
        if (a != address(this) && b != address(this)) return false;
        return _addressGetter(dexFactory, abi.encodeWithSignature("getPair(address,address)", a, b)) == account;
    }
    /// @dev Conventional pool detection before graduation is a heuristic, not a
    ///      universal ban on third-party custom contracts or constructor transfers.
    function _restrictedPool(address account) private view returns (bool) {
        if (account == pair && account != address(0)) return true;
        if (account == portal || account.code.length == 0) return false;
        return _addressGetter(account, abi.encodeWithSignature("token0()")) == address(this)
            || _addressGetter(account, abi.encodeWithSignature("token1()")) == address(this);
    }
    function _syncShare(address account) private {
        if (dividend == address(0) || account == address(0)) return;
        bool excluded = account == DEAD || account == address(this) || account == portal
            || account == router || account == dividend || account == swapReceiver || isTaxPool(account);
        ADDClaimDividendV1(payable(dividend)).setShare(account, excluded ? 0 : balanceOf(account));
    }
    function _update(address from, address to, uint256 amount) internal override {
        if (from == address(0)) {
            if (!(initialized && !minted && msg.sender == initializationFactory
                && to == portal && amount == initialSupply)) revert MintForbidden(); minted = true;
        } else {
            if (!(to != address(0) && balanceOf(from) >= amount)) revert InvalidTransfer();
            if (!(to != portal || msg.sender == portal)) revert UsePortalToSell();
            if (!(phase != Phase.AwaitingAdmission)) revert NotAdmitted();
            if (phase == Phase.Active || phase == Phase.RefundOnly || phase == Phase.Refunded)
                if (_restrictedPool(from) || _restrictedPool(to)) revert PoolTransfersLocked();
            if (phase == Phase.Migrating) if (!(from == portal && to == pair)) revert MigrationTransferOnly();
            // Native marketing/reward callbacks cannot recursively trade while
            // OLD tax is being processed ahead of the original seller's input.
            if (automaticProcessing) if (!(from == address(this) || from == dividend)) revert NestedTaxTransfer();
        }
        uint256 tax;
        if (from != address(0) && phase == Phase.Graduated && from != address(this)
            && from != dividend && to != address(this) && to != dividend) {
            bool fromPool = isTaxPool(from); bool toPool = isTaxPool(to);
            if (amount > 0 && toPool && !fromPool) _triggerTaxes();
            tax = FullMath.mulDiv(amount, fromPool ? config.buyTaxBps : toPool ? config.sellTaxBps : 0, 10000);
        }
        if (tax > 0) { super._update(from, address(this), tax); emit TradeTax(from, to, tax); }
        super._update(from, to, amount-tax);
        _syncShare(from); if (to != from) _syncShare(to);
    }
    function unprocessedTokens() public view returns (uint256) {
        return balanceOf(address(this)) - pendingLPToken - pendingSelfReward;
    }
    function _triggerTaxes() private {
        if (unprocessedTokens() == 0 && pendingMarketing == 0 && pendingDividendQuote == 0
            && pendingSelfReward == 0 && pendingLPToken == 0 && pendingLPQuote == 0) return;
        if (!(gasleft() >= AUTO_CALL_GAS + AUTO_CALL_GAS/63 + TRADE_GAS_RESERVE)) revert TaxTradeGasLimitTooLow();
        bytes memory data = abi.encodeWithSelector(this.processTaxes.selector); bool ok;
        uint256 allowance_ = AUTO_CALL_GAS;
        assembly ("memory-safe") { ok := call(allowance_, address(), 0, add(data,32), mload(data), 0, 0) }
        if (!ok) emit AutomaticProcessingDeferred();
    }

    /// @notice Permissionless retry, same bounded pipeline as sell-triggered processing.
    ///         Caller cannot set paths, minimum outputs, amounts or payout receivers.
    function processTaxes() external nonReentrant {
        if (!(phase == Phase.Graduated)) revert NotGraduated();
        if (!(gasleft() >= 3_100_000)) revert TaxProcessingGasLimitTooLow();
        automaticProcessing = true;
        _observe(address(this), quoteToken);
        if (config.dividendBps > 0 && config.rewardMode != RewardMode.Self && rewardAsset != quoteToken) {
            if (quoteToken != wrappedNative && rewardAsset != wrappedNative) {
                _observe(quoteToken, wrappedNative); _observe(wrappedNative, rewardAsset);
            } else _observe(quoteToken, rewardAsset);
        }
        _stage(abi.encodeWithSelector(this.autoTax.selector), 600_000);
        if (dividend != address(0)) _stage(abi.encodeWithSelector(this.autoFund.selector), 900_000);
        _stage(abi.encodeWithSelector(this.autoLiquidity.selector), 450_000);
        bool paid = _stage(abi.encodeWithSelector(this.autoMarketing.selector, quoteToken == wrappedNative), 100_000);
        if (!paid && quoteToken == wrappedNative) _stage(abi.encodeWithSelector(this.autoMarketing.selector, false), 70_000);
        automaticProcessing = false;
    }
    function _stage(bytes memory data, uint256 allowance_) private returns (bool ok) {
        assembly ("memory-safe") { ok := call(allowance_, address(), 0, add(data,32), mload(data), 0, 0) }
        bytes4 selector; assembly ("memory-safe") { selector := mload(add(data,32)) }
        emit AutomaticStage(selector, ok);
    }
    function _observe(address input, address output) private {
        _stage(abi.encodeWithSelector(this.observePair.selector, input, output), 140_000);
    }
    function observePair(address input, address output) external onlySelf { prices.observe(router, input, output); }

    function _split(uint256 amount, uint256[4] memory weights) private pure returns (uint256[4] memory parts) {
        uint256 denominator; uint256 first = 4; uint256 used;
        for (uint256 i; i < 4; i++) { denominator += weights[i]; if (first == 4 && weights[i] > 0) first = i; }
        if (!(denominator > 0)) revert EmptySplit();
        for (uint256 i; i < 4; i++) { parts[i] = FullMath.mulDiv(amount, weights[i], denominator); used += parts[i]; }
        parts[first] += amount-used;
    }
    function _parts(uint256 amount) private view returns (uint256[4] memory) {
        return _split(amount, [uint256(config.marketingBps), uint256(config.burnBps), uint256(config.dividendBps), uint256(config.liquidityBps)]);
    }
    function _salePortion(uint256 amount) private view returns (uint256) {
        uint256[4] memory p = _parts(amount);
        return p[0] + (config.rewardMode == RewardMode.Self ? 0 : p[2]) + p[3] - p[3]/2;
    }
    function _swap(uint256 amount, uint256 minimum, address[] memory path) private returns (uint256 received) {
        if (!(amount > 0 && minimum > 0)) revert SwapNeedsMinimum();
        IERC20Minimal input = IERC20Minimal(path[0]); IERC20Minimal output = IERC20Minimal(path[path.length-1]);
        uint256 beforeInput = input.balanceOf(address(this)); uint256 beforeOutput = output.balanceOf(address(this));
        uint256 beforeTransit = output.balanceOf(swapReceiver);
        input.safeApprove(router,0); input.safeApprove(router,amount);
        // V2 INVALID_TO disallows address(this) as the recipient of our own-token swap.
        // Only the fresh balance delta is collected; pre-existing donations are not allocated.
        IADDTaxRouter(router).swapExactTokensForTokensSupportingFeeOnTransferTokens(amount,minimum,path,swapReceiver,block.timestamp);
        ADDTaxSwapReceiverV1(swapReceiver).collect(address(output),output.balanceOf(swapReceiver)-beforeTransit);
        input.safeApprove(router,0);
        if (!(beforeInput - input.balanceOf(address(this)) == amount)) revert UnexpectedSwapDebit();
        received = output.balanceOf(address(this)) - beforeOutput;
        if (!(received >= minimum)) revert InsufficientSwapOutput();
    }
    /// @dev Each stage executes in a rollback-isolated self call. Failures retain
    ///      allocations and do not silently mark rewards paid or burn user reserves.
    function autoTax() external onlySelf {
        uint256 amount = unprocessedTokens(); if (amount < processingThreshold()) return;
        if (amount > maximumProcessAmount) amount = maximumProcessAmount;
        uint256 sale = _salePortion(amount); uint256 minimum;
        address[] memory path = new address[](2); path[0] = address(this); path[1] = quoteToken;
        if (sale > 0) {
            (uint256 bounded,) = prices.quote(router,path,sale);
            if (bounded < sale) amount = FullMath.mulDiv(amount,bounded,sale);
            sale = _salePortion(amount);
            (bounded,minimum) = prices.quote(router,path,sale);
            if (!(bounded == sale)) revert RoundedSwapCapacity();
        }
        uint256[4] memory p = _parts(amount);
        if (p[1] > 0) { totalBurned += p[1]; _transfer(address(this),DEAD,p[1]); }
        uint256 rewardSale = p[2];
        if (config.rewardMode == RewardMode.Self) { pendingSelfReward += p[2]; rewardSale = 0; }
        uint256 keepLP = p[3]/2; uint256 sellLP = p[3]-keepLP; pendingLPToken += keepLP;
        uint256 received;
        if (sale > 0) {
            received = _swap(sale,minimum,path);
            uint256[4] memory q = _split(received,[p[0],rewardSale,sellLP,uint256(0)]);
            pendingMarketing += q[0]; pendingDividendQuote += q[1]; pendingLPQuote += q[2];
        }
        emit TaxProcessed(amount,p[1],received);
    }
    function autoFund() external onlySelf {
        uint256 amount = config.rewardMode == RewardMode.Self ? pendingSelfReward : pendingDividendQuote;
        if (amount == 0) return;
        uint256 output = amount; uint256 minimum = amount;
        if (config.rewardMode == RewardMode.Self) pendingSelfReward -= amount;
        else {
            if (rewardAsset != quoteToken) {
                bool via = quoteToken != wrappedNative && rewardAsset != wrappedNative;
                address[] memory path = new address[](via ? 3 : 2); path[0] = quoteToken; path[path.length-1] = rewardAsset;
                if (via) path[1] = wrappedNative;
                (amount,minimum) = prices.quote(router,path,amount);
                output = _swap(amount,minimum,path);
            }
            pendingDividendQuote -= amount;
        }
        IERC20Minimal asset = IERC20Minimal(rewardAsset);
        uint256 beforeBalance = asset.balanceOf(address(this));
        asset.safeApprove(dividend,0); asset.safeApprove(dividend,output);
        uint256 received = ADDClaimDividendV1(payable(dividend)).depositRewards(output);
        asset.safeApprove(dividend,0);
        if (!(beforeBalance - asset.balanceOf(address(this)) == output && received >= minimum)) revert InvalidRewardFunding();
    }
    function autoLiquidity() external onlySelf {
        if (pendingLPToken == 0 || pendingLPQuote == 0) return;
        (uint256 rt,uint256 rq,) = prices.checkedPrice(router,address(this),quoteToken);
        uint256 t = pendingLPToken;
        if (t > maximumProcessAmount) t = maximumProcessAmount;
        if (t > rt/1000) t = rt/1000;
        uint256 q = FullMath.mulDiv(t,rq,rt);
        if (q > pendingLPQuote) { q = pendingLPQuote; t = FullMath.mulDiv(q,rt,rq); }
        uint256 minT = FullMath.mulDiv(t,9700,10000); uint256 minQ = FullMath.mulDiv(q,9700,10000);
        if (!(minT > 0 && minQ > 0)) revert LPAmountTooSmall();
        uint256 beforeLP = IERC20Minimal(pair).balanceOf(DEAD);
        uint256 beforeT = balanceOf(address(this)); uint256 beforeQ = IERC20Minimal(quoteToken).balanceOf(address(this));
        _approve(address(this),router,t);
        IERC20Minimal(quoteToken).safeApprove(router,0); IERC20Minimal(quoteToken).safeApprove(router,q);
        (uint256 usedT,uint256 usedQ,uint256 lp) = IADDTaxRouter(router).addLiquidity(address(this),quoteToken,t,q,minT,minQ,DEAD,block.timestamp);
        _approve(address(this),router,0); IERC20Minimal(quoteToken).safeApprove(router,0);
        if (!(usedT >= minT && usedT <= t && usedQ >= minQ && usedQ <= q
            && beforeT-balanceOf(address(this)) == usedT
            && beforeQ-IERC20Minimal(quoteToken).balanceOf(address(this)) == usedQ)) revert InvalidLPConsumption();
        if (!(lp > 0 && IERC20Minimal(pair).balanceOf(DEAD) >= beforeLP+lp)) revert LPNotBurned();
        pendingLPToken -= usedT; pendingLPQuote -= usedQ; totalLiquidity += lp;
        emit LiquidityBurned(usedT,usedQ,lp);
    }
    function autoMarketing(bool unwrapNative) external onlySelf {
        uint256 amount = pendingMarketing; if (amount == 0) return; pendingMarketing = 0;
        if (unwrapNative) {
            if (!(quoteToken == wrappedNative)) revert NotNativeQuote();
            IADDClaimWrappedV1(wrappedNative).withdraw(amount);
            (bool ok,) = payable(config.marketingWallet).call{value:amount,gas:30000}("");
            if (!(ok)) revert MarketingNativeRejected();
        } else {
            uint256 beforeBalance = IERC20Minimal(quoteToken).balanceOf(address(this));
            IERC20Minimal(quoteToken).safeTransfer(config.marketingWallet,amount);
            if (!(beforeBalance-IERC20Minimal(quoteToken).balanceOf(address(this)) == amount)) revert UnexpectedMarketingDebit();
        }
        emit MarketingPaid(config.marketingWallet,amount,unwrapNative);
    }
    receive() external payable { if (!(msg.sender == wrappedNative)) revert OnlyWrappedNative(); }
}

contracts/tax-v1/ADDClaimDividendV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../openzeppelin/SafeERC20.sol";
import "../openzeppelin/ReentrancyGuard.sol";
import "../FullMath.sol";

interface IADDClaimTaxTokenV1 {
    function liquidityAdded() external view returns (bool);
    function automaticProcessing() external view returns (bool);
}
interface IADDClaimWrappedV1 { function withdraw(uint256 amount) external; }

/// @title ADD 专属领取式分红 / per-token claim ledger, candidate V1
/// @notice 每个启用分红的代币独立部署；奖励入账时分配权益，持有人自行领取。
/// @dev No owner, upgrade, sweep, receiver change, or balance-based claim-time snapshot.
///      The factory binds one token and one reward asset once. Never share this ledger
///      between launch tokens. Rebasing rewards and sender-extra-fee rewards are unsupported.
contract ADDClaimDividendV1 is ReentrancyGuard {
    using SafeERC20 for IERC20Minimal;
    // Portal V1 inventory is bounded by uint112 per half, well below this scale.
    uint256 private constant SCALE = 1e36;
    address public immutable initializationFactory;
    bool private initialized;
    address public token;
    address public rewardToken;
    address public wrappedNative;
    bool public nativeReward;
    uint256 public minimumHolding;
    uint256 public totalShares;
    uint256 public rewardPerShare;
    uint256 public totalFunded;
    uint256 public totalClaimed;
    struct Account { uint256 share; uint256 index; uint256 credit; uint256 fraction; }
    mapping(address => Account) public accounts;

    event RewardsDeposited(uint256 actualReceived, uint256 eligibleShares, uint256 index);
    event ShareUpdated(address indexed holder, uint256 share);
    event RewardClaimed(address indexed holder, uint256 amount, bool nativePayment);

    constructor() { initializationFactory = msg.sender; initialized = true; }

    /// @dev Implementation is locked. Only its deploying factory can initialize clones.
    function initialize(address token_, address reward_, address wrapped_, bool native_, uint256 minimum) external {
        require(msg.sender == initializationFactory && !initialized, "Dividend initialization forbidden");
        require(token_.code.length > 0 && reward_.code.length > 0 && wrapped_.code.length > 0, "Invalid dividend assets");
        require(minimum >= 10_000 ether && (!native_ || reward_ == wrapped_), "Invalid dividend parameters");
        initialized = true;
        token = token_; rewardToken = reward_; wrappedNative = wrapped_;
        nativeReward = native_; minimumHolding = minimum;
    }

    /// @dev Prevent reward-asset callbacks from claiming midway through automatic conversion.
    ///      setShare deliberately remains callable by the token during a self-token claim.
    modifier outsideProcessing() {
        require(!IADDClaimTaxTokenV1(token).automaticProcessing(), "Tax processing active"); _;
    }

    function _settle(address holder) private {
        Account storage a = accounts[holder];
        uint256 delta = rewardPerShare - a.index;
        uint256 fraction = mulmod(a.share, delta, SCALE) + a.fraction;
        a.credit += FullMath.mulDiv(a.share, delta, SCALE) + fraction / SCALE;
        a.fraction = fraction % SCALE; a.index = rewardPerShare;
    }

    /// @notice 先结算旧持仓，再更新份额；卖出不会丢掉已记账的奖励。
    /// @dev Token-only, O(1), no recipient calls. Must never silently skip decreases.
    ///      Infrastructure/pairs must be passed zero by the bound token.
    function setShare(address holder, uint256 balance) external {
        require(msg.sender == token, "Only bound token");
        _settle(holder);
        Account storage a = accounts[holder];
        uint256 next = balance >= minimumHolding ? balance : 0;
        totalShares = totalShares - a.share + next; a.share = next;
        emit ShareUpdated(holder, next);
    }

    function claimable(address holder) public view returns (uint256) {
        Account memory a = accounts[holder]; uint256 delta = rewardPerShare - a.index;
        return a.credit + FullMath.mulDiv(a.share, delta, SCALE)
            + (mulmod(a.share, delta, SCALE) + a.fraction) / SCALE;
    }

    /// @notice Only the bound tax token funds rewards; ordinary transfers are donations,
    ///         not deposits, and cannot steal or reallocate another holder's entitlement.
    /// @dev Actual balance delta is credited. Funding with zero eligible shares reverts,
    ///      leaving funds pending at the tax token. No loops or payout rounds run here.
    function depositRewards(uint256 amount) external nonReentrant returns (uint256 received) {
        require(msg.sender == token, "Only bound token");
        require(IADDClaimTaxTokenV1(token).liquidityAdded(), "Not graduated");
        require(amount > 0 && totalShares > 0, "No eligible shares or amount");
        uint256 shares = totalShares;
        uint256 beforeBalance = IERC20Minimal(rewardToken).balanceOf(address(this));
        IERC20Minimal(rewardToken).safeTransferFrom(msg.sender, address(this), amount);
        received = IERC20Minimal(rewardToken).balanceOf(address(this)) - beforeBalance;
        require(totalShares == shares, "Shares changed during funding");
        uint256 increment = FullMath.mulDiv(received, SCALE, shares);
        require(increment > 0, "Reward too small");
        rewardPerShare += increment; totalFunded += received;
        emit RewardsDeposited(received, shares, rewardPerShare);
    }

    /// @notice DApp 领取入口。unwrapNative=true 仅用于原生币奖励；false 领取 WBNB/ERC20。
    function claim(bool unwrapNative) external outsideProcessing nonReentrant returns (uint256) {
        return _claim(msg.sender, unwrapNative);
    }

    /// @notice Anyone can pay gas for a holder; rewards always go to that holder.
    function claimFor(address holder) external outsideProcessing nonReentrant returns (uint256) {
        return _claim(holder, false);
    }

    function _claim(address holder, bool unwrapNative) private returns (uint256 amount) {
        require(!unwrapNative || nativeReward, "Not native reward");
        _settle(holder); Account storage a = accounts[holder]; amount = a.credit;
        if (amount == 0) return 0;
        a.credit = 0; totalClaimed += amount;
        uint256 beforeBalance = IERC20Minimal(rewardToken).balanceOf(address(this));
        if (unwrapNative) {
            IADDClaimWrappedV1(wrappedNative).withdraw(amount);
            (bool ok,) = payable(holder).call{value: amount}("");
            require(ok, "Native reward rejected");
        } else IERC20Minimal(rewardToken).safeTransfer(holder, amount);
        uint256 afterBalance = IERC20Minimal(rewardToken).balanceOf(address(this));
        // Reject sender-side extra fees. Failed payments revert credit AND asset movement.
        require(beforeBalance >= afterBalance && beforeBalance - afterBalance == amount, "Unexpected reward debit");
        emit RewardClaimed(holder, amount, unwrapNative);
    }

    receive() external payable { require(msg.sender == wrappedNative, "Only wrapped native"); }
}

contracts/tax-v1/ADDTaxSwapReceiverV1.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "../openzeppelin/SafeERC20.sol";

/// @notice V2 output transit only. A V2 pair forbids its token0/token1 as swap recipients,
///         so tax-token -> quote swaps cannot send their output directly to the tax token.
/// @dev No tax/accounting decisions, approvals, owner, arbitrary recipient or upgrade.
///      The factory creates one receiver per token; only that token may collect to itself.
contract ADDTaxSwapReceiverV1 {
    using SafeERC20 for IERC20Minimal;
    address public immutable token;
    constructor(address token_) { require(token_.code.length > 0, "Invalid token"); token = token_; }
    function collect(address asset, uint256 amount) external {
        require(msg.sender == token, "Only bound token");
        IERC20Minimal(asset).safeTransfer(token, amount);
    }
}

contracts/tax/ADDTaxPriceGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDTaxTypes.sol";
import "../FullMath.sol";
import "../openzeppelin/SafeERC20.sol";

interface IADDTaxPair {
    function token0() external view returns(address);
    function getReserves() external view returns(uint112,uint112,uint32);
    function price0CumulativeLast() external view returns(uint256);
    function price1CumulativeLast() external view returns(uint256);
}
interface IADDTaxPairFactory { function getPair(address,address) external view returns(address); }

/// @notice V2 cumulative-price guard for automatic tax conversions; not a price oracle for user trades.
/// @dev Uses the V2 counterfactual cumulative algorithm, including intentional uint32/uint256 wraparound.
///      A new/idle market needs two observations 5–30 minutes apart. Missing/stale data defers processing.
///      This bounds spot deviation/size/slippage; it cannot eliminate sustained manipulation or MEV.
library ADDTaxPriceGuard {
    uint256 internal constant Q112=2**112;
    uint32 internal constant WINDOW=300;
    uint32 internal constant MAX_AGE=1800;
    struct Observation {
        uint256 cumulative0; uint256 cumulative1;
        uint224 average0; uint224 average1;
        uint32 timestamp; uint32 averageAt;
        bool initialized; bool ready;
    }
    struct State { mapping(address=>Observation) observations; }

    function pairFor(address router,address input,address output) internal view returns(address pair) {
        pair=IADDTaxPairFactory(IADDTaxRouter(router).factory()).getPair(input,output);
        require(pair.code.length>0,"Auto pair unavailable");
    }
    function reserves(address pair,address input,address output) internal view returns(uint256 rin,uint256 rout,bool forward) {
        (uint112 r0,uint112 r1,)=IADDTaxPair(pair).getReserves();
        forward=IADDTaxPair(pair).token0()==input; (rin,rout)=forward?(uint256(r0),uint256(r1)):(uint256(r1),uint256(r0));
        require(rin>0 && rout>0,"Auto empty pool");
        // An in-flight multi-hop swap or manual LP deposit can already have sent the OTHER asset to the pool.
        // Never consume that input in our own swap or use an un-synced donation as an observation.
        require(IERC20Minimal(input).balanceOf(pair)==rin && IERC20Minimal(output).balanceOf(pair)==rout,"Auto pool busy");
    }
    function observe(State storage self,address router,address input,address output) internal {
        address pair=pairFor(router,input,output);
        reserves(pair,input,output);
        (uint112 r0,uint112 r1,uint32 updated)=IADDTaxPair(pair).getReserves();
        uint256 c0=IADDTaxPair(pair).price0CumulativeLast(); uint256 c1=IADDTaxPair(pair).price1CumulativeLast();
        uint32 now32=uint32(block.timestamp);
        unchecked {
            uint32 elapsed=now32-updated;
            c0+=uint256((uint224(r1)<<112)/r0)*elapsed;
            c1+=uint256((uint224(r0)<<112)/r1)*elapsed;
        }
        Observation storage o=self.observations[pair]; uint32 age;
        unchecked { age=now32-o.timestamp; }
        if(!o.initialized || age>MAX_AGE) {
            o.initialized=true; o.ready=false; o.average0=0; o.average1=0; o.averageAt=0;
        } else if(age>=WINDOW) {
            unchecked { o.average0=uint224((c0-o.cumulative0)/age); o.average1=uint224((c1-o.cumulative1)/age); }
            o.averageAt=now32; o.ready=true;
        } else return; // Do not let frequent trades continually restart the observation window.
        o.timestamp=now32; o.cumulative0=c0; o.cumulative1=c1;
    }
    function checkedPrice(State storage self,address router,address input,address output)
        internal view returns(uint256 rin,uint256 rout,uint256 average) {
        address pair=pairFor(router,input,output); bool forward;
        (rin,rout,forward)=reserves(pair,input,output);
        Observation storage o=self.observations[pair]; uint32 age;
        unchecked { age=uint32(block.timestamp)-o.averageAt; }
        require(o.ready && age<=MAX_AGE,"Auto price warming or stale");
        average=forward?o.average0:o.average1; require(average>0,"Auto zero price");
        uint256 spot=FullMath.mulDiv(rout,Q112,rin);
        require(spot>=FullMath.mulDiv(average,9500,10000) && spot<=FullMath.mulDiv(average,10500,10000),"Auto price deviation");
    }
    /// @dev Cap EACH route hop at 0.1% of input reserve. Reverse spot conversion of downstream capacity is
    ///      conservative because V2 fees/price impact reduce actual intermediate output. No unlimited backlog swap.
    function quote(State storage self,address router,address[] memory path,uint256 requested)
        internal view returns(uint256 amount,uint256 minimum) {
        uint256 capacity=type(uint256).max;
        for(uint256 i=path.length-1;i>0;i--) {
            (uint256 rin,uint256 rout,)=checkedPrice(self,router,path[i-1],path[i]);
            uint256 cap=rin/1000;
            if(capacity!=type(uint256).max) {
                uint256 upstream=FullMath.mulDiv(capacity,rin,rout); if(upstream<cap) cap=upstream;
            }
            capacity=cap;
        }
        amount=requested<capacity?requested:capacity; require(amount>0,"Auto amount too small");
        uint256 expected=amount;
        for(uint256 i;i+1<path.length;i++) {
            (,,uint256 average)=checkedPrice(self,router,path[i],path[i+1]);
            expected=FullMath.mulDiv(FullMath.mulDiv(expected,average,Q112),9975,10000);
        }
        uint256[] memory spot=IADDTaxRouter(router).getAmountsOut(amount,path);
        uint256 spotOut=spot[spot.length-1];
        // Both the established time average and current quote impose a NON-ZERO 3% bound.
        minimum=FullMath.mulDiv(expected>spotOut?expected:spotOut,9700,10000);
        require(minimum>0 && spotOut>=minimum,"Auto minimum unavailable");
    }
}

contracts/tax/ADDTaxTypes.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

library ADDTaxTypes {
    uint256 internal constant BPS = 10_000;
    // Initial release policy: each direction may charge at most 10%, fixed at creation.
    uint256 internal constant MAX_TAX_BPS = 1_000;
    enum RewardMode { BNB, Token, Self }
    struct Config {
        uint16 buyTaxBps;
        uint16 sellTaxBps;
        uint16 marketingBps;
        uint16 burnBps;
        uint16 dividendBps;
        uint16 liquidityBps;
        address marketingWallet;
        address operator; // Manual bounded maintenance fallback; automatic trades do not require this signature.
        RewardMode rewardMode;
        address rewardToken;
        uint256 minimumHolding;
    }
    function validate(Config memory c) internal view {
        require(c.buyTaxBps <= MAX_TAX_BPS && c.sellTaxBps <= MAX_TAX_BPS, "Tax exceeds 10%");
        require(c.buyTaxBps > 0 || c.sellTaxBps > 0, "Use zero-tax template");
        require(uint256(c.marketingBps)+c.burnBps+c.dividendBps+c.liquidityBps == BPS, "Allocation must total 100%");
        require(c.marketingBps == 0 || (c.marketingWallet != address(0) && c.marketingWallet != address(0xdead)), "Invalid marketing wallet");
        require(c.operator != address(0) && c.operator != address(0xdead), "Invalid operator");
        require(c.minimumHolding <= 1_000_000_000 ether, "Holding threshold exceeds supply");
        if(c.rewardMode == RewardMode.Token) require(c.rewardToken.code.length > 0, "Reward must be a token");
        else require(c.rewardToken == address(0), "Unexpected reward address");
    }
}

interface IADDTaxRouter {
    function factory() external view returns(address);
    function WETH() external view returns(address);
    function getAmountsOut(uint256,address[] calldata) external view returns(uint256[] memory);
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(uint256,uint256,address[] calldata,address,uint256) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(uint256,address[] calldata,address,uint256) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(uint256,uint256,address[] calldata,address,uint256) external;
    function addLiquidity(address,address,uint256,uint256,uint256,uint256,address,uint256) external returns(uint256,uint256,uint256);
}
interface IADDTaxLifecycle { function liquidityAdded() external view returns(bool); }
interface IADDTaxModules { function taxProcessor() external view returns(address); }
interface IADDTaxAutomaticState { function automaticActive() external view returns(bool); }
interface IADDTaxWrapped { function withdraw(uint256) external; }

library ADDTaxClones {
    function code(address implementation) internal pure returns(bytes memory) {
        return abi.encodePacked(hex"3d602d80600a3d3981f3363d3d373d3d3d363d73",implementation,hex"5af43d82803e903d91602b57fd5bf3");
    }
    function clone(address implementation) internal returns(address instance) {
        bytes memory creation=code(implementation);
        assembly ("memory-safe") { instance := create(0,add(creation,32),mload(creation)) }
        require(instance != address(0), "Clone failed");
    }
}
